import React from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';

const AboutSection = styled.section`
  padding: 120px 0;
  background: #fff;
  position: relative;
  overflow: hidden;
`;

const BackgroundPattern = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(45deg, #f8f8f8 25%, transparent 25%), 
              linear-gradient(-45deg, #f8f8f8 25%, transparent 25%), 
              linear-gradient(45deg, transparent 75%, #f8f8f8 75%), 
              linear-gradient(-45deg, transparent 75%, #f8f8f8 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  opacity: 0.3;
  z-index: 1;
`;

const Container = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  position: relative;
  z-index: 2;
`;

const ContentGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
    gap: 40px;
  }
`;

const TextContent = styled(motion.div)`
  h2 {
    font-size: 3rem;
    font-weight: 300;
    margin-bottom: 40px;
    text-transform: uppercase;
    letter-spacing: -1px;
    color: #000;
  }

  p {
    font-size: 1.1rem;
    line-height: 1.8;
    margin-bottom: 25px;
    color: #333;
    text-align: justify;
  }

  .highlight {
    font-weight: 600;
    color: #000;
  }

  .signature {
    font-size: 1.2rem;
    font-weight: 500;
    color: #000;
    margin-top: 30px;
    text-align: center;
    font-style: italic;
  }
`;

const VisualContent = styled(motion.div)`
  position: relative;
  height: 500px;
  background: linear-gradient(135deg, #000 0%, #333 100%);
  border-radius: 15px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(45deg, transparent 30%, rgba(255, 255, 255, 0.1) 50%, transparent 70%);
    animation: shine 3s infinite;
  }

  @keyframes shine {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
  }
`;

const LogoDisplay = styled.div`
  text-align: center;
  color: #fff;
`;

const LogoMain = styled.div`
  font-size: 4rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: -2px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
`;

const LetterV = styled.span`
  font-size: 4.5rem;
  margin-right: 4px;
`;

const LetterA = styled.span`
  position: relative;
  display: inline-block;

  &::after {
    content: '+';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 1.5rem;
    font-weight: 900;
    color: #fff;
    opacity: 0.8;
  }
`;

const LogoSubtitle = styled.div`
  font-size: 1.2rem;
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: 4px;
  opacity: 0.8;
`;

const StatsContainer = styled(motion.div)`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  margin-top: 60px;
  padding-top: 60px;
  border-top: 1px solid #eee;
`;

const StatItem = styled.div`
  text-align: center;

  .number {
    font-size: 2.5rem;
    font-weight: 700;
    color: #000;
    margin-bottom: 10px;
  }

  .label {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #666;
  }
`;

const AboutUs = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 50 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.8,
        ease: "easeOut"
      }
    }
  };

  const visualVariants = {
    hidden: { opacity: 0, scale: 0.8, rotateY: -15 },
    visible: {
      opacity: 1,
      scale: 1,
      rotateY: 0,
      transition: {
        duration: 1.2,
        ease: "easeOut"
      }
    }
  };

  return (
    <AboutSection>
      <BackgroundPattern />
      <Container>
        <motion.div
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
        >
          <ContentGrid>
            <TextContent variants={itemVariants}>
              <h2>Quem Somos</h2>
              <p>
                A <span className="highlight">Vmais Comunicação</span> nasceu para transformar ideias em resultados. Somos uma agência de publicidade e produtora de vídeo com atuação regional e visão de expansão, especializada em criar estratégias criativas que aproximam marcas do seu público.
              </p>
              <p>
                Unimos clareza, agilidade e profissionalismo para entregar soluções completas em marketing, gestão de redes sociais, produção audiovisual, design e comunicação institucional. Nosso diferencial está na produção interna de conteúdos e na presença do fundador, <span className="highlight">Valdy Lins</span>, como rosto da marca, fortalecendo a confiança e a proximidade com cada cliente.
              </p>
              <p>
                Acreditamos que cada projeto é único e merece ser tratado com dedicação e estratégia. Por isso, trabalhamos lado a lado com pequenos e médios empresários, instituições públicas e influenciadores locais, ajudando-os a se destacar em um mercado cada vez mais competitivo.
              </p>
              <div className="signature">
                "Na Vmais, comunicação é mais que serviço: é parceria, é criatividade, é resultado."
              </div>
            </TextContent>

            <VisualContent variants={visualVariants}>
              <LogoDisplay>
                <LogoMain>
                  <LetterV>V</LetterV>
                  <LetterA>m</LetterA>
                  <LetterA>a</LetterA>
                  <LetterA>i</LetterA>
                  <LetterA>s</LetterA>
                </LogoMain>
                <LogoSubtitle>Comunicação</LogoSubtitle>
              </LogoDisplay>
            </VisualContent>
          </ContentGrid>

          <StatsContainer variants={itemVariants}>
            <StatItem>
              <div className="number">100+</div>
              <div className="label">Projetos Realizados</div>
            </StatItem>
            <StatItem>
              <div className="number">50+</div>
              <div className="label">Clientes Satisfeitos</div>
            </StatItem>
            <StatItem>
              <div className="number">5+</div>
              <div className="label">Anos de Experiência</div>
            </StatItem>
          </StatsContainer>
        </motion.div>
      </Container>
    </AboutSection>
  );
};

export default AboutUs;
